bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,database:env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch();
try{
 const cols=(await pool.query("SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='videobot_listings' AND column_name IN ('creator_terms_version','creator_terms_url','paid_video_file_size_bytes') ORDER BY column_name")).rows.map(x=>x.column_name);
 console.log('SCHEMA_COLUMNS_PRESENT='+JSON.stringify(cols));
 const list=(await pool.query("SELECT DISTINCT l.paid_video_file_id FROM videobot_listings l JOIN videobot_post_receipts r ON r.listing_id=l.listing_id WHERE r.sale_mode='paid_media' AND r.status='sent' AND l.paid_video_file_id IS NOT NULL LIMIT 6")).rows;
 console.log('DISTINCT_PAID_VIDEO_FILE_REFS='+list.length);
 const token=readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE);
 for(let i=0;i<list.length;i++){
  try{
   const response=await net.fetch('https://api.telegram.org/bot'+token+'/getFile',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({file_id:list[i].paid_video_file_id}),signal:AbortSignal.timeout(25000),redirect:'error'});
   const reply=await response.json();
   let reason='OTHER_UNCLASSIFIED';
   const desc=String(reply?.description??'').toLowerCase();
   if(/too big|file.*large|size/.test(desc))reason='FILE_TOO_BIG';
   else if(/wrong file identifier|file_id|file identifier|not found/.test(desc))reason='INVALID_OR_UNKNOWN_FILE_ID';
   else if(/bad request/.test(desc))reason='BAD_REQUEST_OTHER';
   else if(reply?.ok===true)reason='SUCCESS';
   console.log('GETFILE_DIAG='+JSON.stringify({index:i,status:response.status,telegramCode:reply?.error_code??null,reason,fileSize:reply?.ok===true?reply.result?.file_size??null:null}));
  }catch(e){console.log('GETFILE_DIAG='+JSON.stringify({index:i,reason:'TRANSPORT_ERROR',errorName:e?.name??'Error'}));}
 }
}finally{await pool.end();await net.close()}
NODE
if mountpoint -q /mnt/g; then
  printf 'LOCAL_VIDEO_SOURCE_MOUNT=YES\n'
  find /mnt/g/Gserver/CreateVdobot -type f -iname '*.mp4' -printf '%s\n' 2>/dev/null | sort -nr | head -15 | awk '{print "LOCAL_MP4_BYTES="$0}'
else printf 'LOCAL_VIDEO_SOURCE_MOUNT=NO\n';fi
